if (which == 0) {
  // Single string
  const char* fmt = "%s"; // non-null, expects 1 const char*
  HUNSPELL_WARNING(stream, fmt, msg.c_str());
} else if (which == 1) {
  // String + int (decimal)
  const char* fmt = "%s %d"; // expects const char*, int
  int n = (int)(u % 1000000); // constrain magnitude
  HUNSPELL_WARNING(stream, fmt, msg.c_str(), n);
} else {
  // String + hex number
  const char* fmt = "%s 0x%08x"; // expects const char*, unsigned int
  HUNSPELL_WARNING(stream, fmt, msg.c_str(), u);
