import random
import string
from typing import List

# This generator targets a generic text string used as:
# - fprintf-like message (potentially containing arbitrary bytes, but safer to keep printable + UTF-8)
# - Hunspell encrypted-dictionary key (free-form, but interesting keys should include various classes)
# - Generic paths are provided by FUZZ_PARAM_FILENAME separately, so we only provide string buffers here.
#
# Strategy:
# - Produce a UTF-8-encoded text string with varied structure selected by seed-driven randomness.
# - Include mixtures of:
#   * ASCII printable words
#   * Digits and hex-looking tokens
#   * Punctuation and format-like sequences ("%s", "%d", "%08x") to exercise fprintf formatting when used as data
#     (note: in the stubs, our string is used as a data argument, not as the format string, so this is safe)
#   * Unicode from several blocks (Latin-1, Greek, Cyrillic, Arabic, Devanagari, emoji)
#   * Edge cases: empty, very short, long but <= 4096 bytes, repeated patterns
#   * Different line endings and null-like substrings (but avoid embedding NUL since callers use C strings)
# - Ensure we never include embedded NUL ("\x00") so C APIs see full buffer.
# - Return the bytes of UTF-8 encoding, bounded to 4096 bytes.

MAX_BYTES = 4096

_ascii_words = [
    "hello", "world", "foo", "bar", "baz", "qux", "hunspell", "aff", "dic",
    "spell", "suggest", "stem", "analyze", "generate", "add", "remove", "key",
]

_formats = ["%s", "%d", "%u", "%08x", "%#x", "%ld", "%zu", "%%", "%p"]

_hex_chunks = [
    "0x", "deadbeef", "cafebabe", "0x12345678", "BEEF", "DEAD", "FEED", "FACE",
]

_punct = list("-_.:,;!?/@#&()+[]{}<>=*^|~$")

# Some representative Unicode ranges sampled sparsely
_unicode_samples = (
    [chr(c) for c in range(0x00A1, 0x00FF)] +  # Latin-1 Supplement (¡..ÿ)
    [chr(c) for c in range(0x0370, 0x03A2)] +  # Greek
    [chr(c) for c in range(0x0400, 0x0450)] +  # Cyrillic
    [chr(c) for c in range(0x0600, 0x061B)] +  # Arabic subset
    [chr(c) for c in range(0x0900, 0x0930)] +  # Devanagari subset
    [
        "🙂", "😀", "😅", "👍", "✅", "✍", "🔤", "🧪", "📚", "📝",
        "é", "ü", "ß", "ñ", "ø", "å"
    ]
)

_line_endings = ["\n", "\r\n", "\r"]

def _rand_word(r: random.Random) -> str:
    choice = r.randint(0, 5)
    if choice == 0:
        return r.choice(_ascii_words)
    if choice == 1:
        return ''.join(r.choices(string.ascii_letters, k=r.randint(1, 12)))
    if choice == 2:
        return ''.join(r.choices(string.ascii_lowercase + string.digits, k=r.randint(2, 16)))
    if choice == 3:
        return r.choice(_hex_chunks)
    if choice == 4:
        # Mix ASCII and Unicode
        core = ''.join(r.choices(string.ascii_letters, k=r.randint(1, 6)))
        uni = ''.join(r.choices(_unicode_samples, k=r.randint(1, 4)))
        return core + uni
    # format-like token as plain text
    return r.choice(_formats)

def _build_key_like(r: random.Random) -> str:
    # Construct an interesting key-shaped string: segments separated by delimiters
    segs: List[str] = []
    n = r.randint(2, 6)
    for _ in range(n):
        base = ''.join(r.choices(string.ascii_letters + string.digits, k=r.randint(2, 10)))
        # optionally append a tiny unicode or hex
        if r.random() < 0.4:
            base += r.choice([r.choice(_unicode_samples), r.choice(_hex_chunks)])
        segs.append(base)
    delim = r.choice(['-', ':', '.', '/', '_', '+'])
    s = delim.join(segs)
    # Optional prefix/suffix markers often used in keys
    if r.random() < 0.3:
        s = "KEY{" + s + "}"
    if r.random() < 0.3:
        s += "=" + ''.join(r.choices(string.ascii_letters + string.digits, k=r.randint(4, 12)))
    return s

def _build_message_like(r: random.Random) -> str:
    # Natural-looking sentence with mixed tokens and occasional line breaks
    parts: List[str] = []
    words = r.randint(4, 40)
    for i in range(words):
        w = _rand_word(r)
        parts.append(w)
        if r.random() < 0.15:
            parts.append(r.choice(_line_endings))
        elif r.random() < 0.25:
            parts.append(r.choice(_punct))
        else:
            parts.append(' ')
    s = ''.join(parts).strip()
    # Add a trailing numeric to hit %d code path contentually
    if r.random() < 0.6:
        s += " " + str(r.randint(-10**6, 10**6))
    # Add a hex-looking tail
    if r.random() < 0.5:
        s += " 0x" + format(r.getrandbits(32), "08x")
    return s

def _build_unicode_heavy(r: random.Random) -> str:
    # Mostly Unicode with some ASCII glue
    chunks = []
    for _ in range(r.randint(5, 30)):
        if r.random() < 0.7:
            chunks.append(''.join(r.choices(_unicode_samples, k=r.randint(1, 5))))
        else:
            chunks.append(''.join(r.choices(string.ascii_letters, k=r.randint(1, 5))))
        if r.random() < 0.2:
            chunks.append(r.choice(_line_endings))
        elif r.random() < 0.3:
            chunks.append(' ')
    return ''.join(chunks).strip()

def _build_repeated_pattern(r: random.Random) -> str:
    base = _build_key_like(r) if r.random() < 0.5 else _build_message_like(r)
    repeat = r.randint(2, 20)
    sep = r.choice(['\n', ' ', ',', ';'])
    s = sep.join([base for _ in range(repeat)])
    return s

def _ensure_no_nul(s: str) -> str:
    # Replace any accidental NULs (shouldn't occur) just in case
    return s.replace('\x00', '\uFFFD')

def _bounded_utf8(s: str) -> bytes:
    b = s.encode('utf-8', errors='strict')
    if len(b) <= MAX_BYTES:
        return b
    # Truncate safely on code point boundary by stepping back if needed
    b = b[:MAX_BYTES]
    # Remove possible split trailing continuation bytes
    while b and (b[-1] & 0xC0) == 0x80:
        b = b[:-1]
    return b

def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Decide profile
    profile = r.randint(0, 6)
    if profile == 0:
        s = ""  # empty string edge case
    elif profile == 1:
        s = _build_key_like(r)
    elif profile == 2:
        s = _build_message_like(r)
    elif profile == 3:
        s = _build_unicode_heavy(r)
    elif profile == 4:
        s = _build_repeated_pattern(r)
    elif profile == 5:
        # Short token: good for C API boundaries
        length = r.randint(1, 32)
        alphabet = string.ascii_letters + string.digits + ''.join(_punct)
        s = ''.join(r.choices(alphabet, k=length))
    else:
        # Long message close to limit
        s = _build_message_like(r)
        # pad with unicode and numbers to approach the limit
        while True:
            extra = _build_unicode_heavy(r)
            s_try = s + "\n" + extra
            if len(s_try.encode('utf-8')) > MAX_BYTES:
                break
            s = s_try

    s = _ensure_no_nul(s)
    return _bounded_utf8(s)
